UPDATE borrow_request
SET status = 'SUCCEEDED', result_code = 'SUCCEEDED', quota_settled = #{settled},
    stock_settled = #{settled}, updated_at = #{now}
WHERE request_id = #{requestId} AND status = 'PROCESSING' AND attempt_token = #{token}

UPDATE borrow_request
SET status = 'RELEASING', result_code = #{resultCode}, updated_at = #{now}
WHERE request_id = #{requestId} AND status = 'PROCESSING' AND attempt_token = #{token}

UPDATE borrow_request
SET status = 'RETRYABLE', quota_settled = 1, stock_settled = 1, updated_at = #{now}
WHERE request_id = #{requestId} AND status = 'RELEASING' AND attempt_token = #{token}

UPDATE borrow_request
SET quota_settled = 1, updated_at = #{now}
WHERE request_id = #{requestId} AND attempt_token = #{token}

UPDATE borrow_request
SET stock_settled = 1, updated_at = #{now}
WHERE request_id = #{requestId} AND attempt_token = #{token}

UPDATE user_lending_account
SET active_count = active_count + 1, version = version + 1, updated_at = #{now}
WHERE user_id = #{userId} AND active_count < #{maxActive}

UPDATE user_lending_account
SET active_count = active_count - 1, version = version + 1, updated_at = #{now}
WHERE user_id = #{userId} AND active_count > 0

UPDATE lending_stock
SET available_copies = available_copies - 1, version = version + 1, updated_at = #{now}
WHERE book_id = #{bookId} AND available_copies > 0

UPDATE lending_stock
SET available_copies = available_copies + 1, version = version + 1, updated_at = #{now}
WHERE book_id = #{bookId} AND available_copies < total_copies

